// Block (composition) — consumer-supplied form fields arranged inside the Dialog Component.
// Dialog owns overlay behavior; Form owns form semantics and validation context.
import { useId } from "react";
import type { FormEvent, ReactNode } from "react";
import {
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../components/Dialog";
import { Form } from "../components/Form";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./FormDialog.css";

export interface FormDialogProps {
  /** Control that opens the dialog. */
  trigger: ReactNode;
  /** Dialog heading. */
  title: string;
  /** Form fields supplied by the consumer. */
  children: ReactNode;
  /** Submit action label. */
  submitLabel?: string;
  /** Called with string-normalized form values on submit. */
  onSubmit?: (data: Record<string, string>) => void;
  /** Puts the submit action in a pending state and blocks re-submit. */
  isPending?: boolean;
}

export function FormDialog({
  trigger,
  title,
  children,
  submitLabel = "Save",
  onSubmit,
  isPending,
}: FormDialogProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const data: Record<string, string> = {};

    formData.forEach((value, key) => {
      data[key] = String(value);
    });

    onSubmit?.(data);
  };

  const formId = useId();
  return (
    <DialogTrigger>
      {trigger}
      <DialogContent
        className="sd-formdialog"
        header={
          <DialogHeader>
            <DialogTitle>{title}</DialogTitle>
          </DialogHeader>
        }
        footer={
          // The footer renders below the scrolling body, outside the <Form>, so `form=` keeps the
          // submit button wired to it (DrawerForm's shape). DialogFooter renders a ButtonGroup,
          // which right-aligns the actions and stacks them full-width on a narrow screen.
          <DialogFooter>
            <Button size="large" type="button" variant="secondary" slot="close">
              Cancel
            </Button>
            <Button size="large" type="submit" form={formId} variant="primary" isPending={isPending}>
              {submitLabel}
            </Button>
          </DialogFooter>
        }
      >
        <Form isPending={isPending} id={formId} onSubmit={handleSubmit}>
          <Stack gap="medium" className="sd-formdialog__fields">
            {children}
          </Stack>
        </Form>
      </DialogContent>
    </DialogTrigger>
  );
}

/* FormDialog.css — .sd-formdialog (Block)
   Arrangement is handled by Stack and DialogFooter; Components own all chrome and look.
   This Block defines no tokens and does not reach into Component internals. */
